'use strict';

/**
* WebAssembly routine to compute the maximum value of a double-precision floating-point strided array according to a mask.
*
* @module @stdlib/stats/strided/wasm/dmskmax
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
* var dmskmax = require( '@stdlib/stats/strided/wasm/dmskmax' );
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* // Perform operation:
* var v = dmskmax.main( x.length, x, 1, mask, 1 );
* // returns 2.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
* var dmskmax = require( '@stdlib/stats/strided/wasm/dmskmax' );
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* // Perform operation:
* var v = dmskmax.ndarray( x.length, x, 1, 0, mask, 1, 0 );
* // returns 2.0
*
* @example
* var Memory = require( '@stdlib/wasm/memory' );
* var oneTo = require( '@stdlib/array/one-to' );
* var zeros = require( '@stdlib/array/zeros' );
* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
* var dmskmax = require( '@stdlib/stats/strided/wasm/dmskmax' );
*
* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
* var mem = new Memory({
*     'initial': 10,
*     'maximum': 100
* });
*
* // Create a new routine:
* var mod = new dmskmax.Module( mem );
* // returns <Module>
*
* // Initialize the routine:
* mod.initializeSync();
*
* // Specify a vector length:
* var N = 5;
*
* // Define pointers (i.e., byte offsets) for storing the input array and mask:
* var xptr = 0;
* var mptr = N * bytesPerElement( 'float64' );
*
* // Write array values to module memory:
* mod.write( xptr, oneTo( N, 'float64' ) );
* mod.write( mptr, zeros( N, 'uint8' ) );
*
* // Perform computation:
* var v = mod.main( N, xptr, 1, mptr, 1 );
*
* console.log( v );
* // => 5.0
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;

// exports: { "Module": "main.Module" }
